	"go.etcd.io/etcd/client/v3/naming/resolver"
	testpb "go.etcd.io/etcd/tests/v3/integration/clientv3/naming/testpb"
	integration2 "go.etcd.io/etcd/tests/v3/integration/v3mux/integration"

	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials/insecure"
)

// testServer is used to implement testpb.TestServiceServer
type testServer struct {
	testpb.UnimplementedTestServiceServer
	name string
}

// UnaryCall implements testpb.TestServiceServer
func (s *testServer) UnaryCall(_ context.Context, _ *testpb.SimpleRequest) (*testpb.SimpleResponse, error) {
	return &testpb.SimpleResponse{Username: s.name}, nil
}

func TestResolverLoadsEndpointsOnInit(t *testing.T) {
	testResolverLoadsEndpointsOnInit(t, "round_robin")
}

func TestResolverLoadsEndpointsOnInitWithPickFirst(t *testing.T) {
	testResolverLoadsEndpointsOnInit(t, "pick_first")
}

func testResolverLoadsEndpointsOnInit(t *testing.T, lbPolicy string) {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	clus := integration2.NewClusterV3(t, &integration2.ClusterConfig{Size: 3})
	defer clus.Terminate(t)

	// Start servers on two endpoints
	e1 := integration2.NewGRPCServer(t, &testServer{name: "e1"})
	defer e1.Close()
	e2 := integration2.NewGRPCServer(t, &testServer{name: "e2"})
	defer e2.Close()

	em, err := endpoints.NewManager(clus.RandClient(), "foo")
	if err != nil {
		t.Fatal("failed to create endpoint manager", err)
	}
	if err := em.AddEndpoint(ctx, "foo/e1", endpoints.Endpoint{Addr: e1.Addr()}); err != nil {
		t.Fatal("failed to add endpoint e1", err)
	}

	b, err := resolver.NewBuilder(clus.Client(1))
	if err != nil {
		t.Fatal("failed to new resolver builder", err)
	}

	// Create connection with provided lb policy
	conn, err := grpc.NewClient("etcd:///foo", grpc.WithTransportCredentials(insecure.NewCredentials()), grpc.WithResolvers(b),
		grpc.WithDefaultServiceConfig(fmt.Sprintf(`{"loadBalancingPolicy":"%s"}`, lbPolicy)))
	if err != nil {
		t.Fatal("failed to connect to foo", err)
	}
	defer conn.Close()

	// Send an initial request that should go to e1
	c := testpb.NewTestServiceClient(conn)
	resp, err := c.UnaryCall(t.Context(), &testpb.SimpleRequest{}, grpc.WaitForReady(true))
	if err != nil {
		t.Fatal("failed to invoke rpc to foo (e1)", err)
	}
	if resp.Username != "e1" {
		t.Errorf("expected response from e1, got %q", resp.Username)
	}

	// Add a second endpoint
	if err := em.AddEndpoint(ctx, "foo/e2", endpoints.Endpoint{Addr: e2.Addr()}); err != nil {
		t.Fatal("failed to add endpoint e2", err)
	}

	// Wait for the resolver to update with the new endpoint
	waitForEndpoints(t, clus.Client(1), "foo", 2)

	// For round_robin, both endpoints should be hit.
	// For pick_first, after the update, we might still see e1 only
	// depending on timing. We just verify no errors occur.
	for i := 0; i < 4; i++ {
		resp, err = c.UnaryCall(t.Context(), &testpb.SimpleRequest{}, grpc.WaitForReady(true))
		if err != nil {
			t.Fatal("failed to invoke rpc to foo (e1/e2)", err)
		}
		t.Logf("response from %s", resp.Username)
	}
}

func waitForEndpoints(t *testing.T, client *clientv3.Client, service string, count int) {
	em, err := endpoints.NewManager(client, service)
	if err != nil {
		t.Fatalf("failed to create endpoint manager: %v", err)
	}
	deadline := time.Now().Add(10 * time.Second)
	for time.Now().Before(deadline) {
		eps, err := em.List(t.Context())
		if err != nil {
			t.Fatalf("failed to list endpoints: %v", err)
		}
		if len(eps) >= count {
			return
		}
		time.Sleep(100 * time.Millisecond)
	}
	t.Fatalf("timed out waiting for %d endpoints", count)
}

